var t=`0839-rasam`;var i=`world-0839`;var s=`IN`;var n=`south-asia`;var r=4;var o=24;var d={en:`Rasam`,ua:`Расам`};var m={en:`Rasam is a India dish made with tomato, tamarind concentrate, sambar powder, fresh curry leaves. This home-scale recipe assigns measured ingredients to the steps where they are used. Sambar powder approximates a rasam spice blend; homemade rasam podi is not cataloged.`,ua:`Расам, страва кухні країни Індія. Основні складники: помідор, концентрат тамаринду, приправа самбар, свіже листя карі. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Суміш самбар наближено замінює спеції для расаму, оскільки расам-поді відсутня.`};var g=[{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 14 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 14 хвилин до м’якості та готовності.`,t:[`simmering`],m:14,i:[[`tomato`,320,`g`],[`tamarind-concentrate`,28,`g`],[`water`,950,`ml`],[`sambar-powder`,12,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 5 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 5 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:5,i:[[`ghee`,28,`g`],[`mustard-seeds`,5,`g`],[`cumin-seeds`,5,`g`],[`fresh-curry-leaves`,12,`leaf`],[`garlic`,3,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:3,i:[[`ground-black-pepper`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,20,`g`]]}];var l={slug:t,id:i,country:`IN`,region:n,servings:4,minutes:24,title:d,text:m,steps:g};export{s as country,l as default,i as id,o as minutes,n as region,r as servings,t as slug,g as steps,m as text,d as title};